{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "A colossal wrought-iron gate hangs crookedly, its hinges rusted. The glass diver stands before it, helmet reflecting the shattered city beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer studies a crumbling map.",
      "visual_description": "Mara kneels on a broken cobblestone street, unrolling a frayed map under a flickering lantern. The tin fox sniffs at a nearby crack.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "A twisted tower looms in the mist, its windows glowing faintly. The oracle lamp sputters, its eye wide, casting long shadows on the wall.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector blocks a narrow archway.",
      "visual_description": "A small stone arch is partially blocked by the sleeping tax collector, who snores with a ledger under his head. Stamped papers flutter in the breeze.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Rumors of a dragon are carved into a wall.",
      "visual_description": "An ancient wall bears a crude carving of a winged beast. The tin fox inspects it while Mara traces the lines with her ink-stained fingers.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver swims through a mirror in a shattered fountain.",
      "visual_description": "A cracked fountain holds a silver mirror shard. The glass diver steps into it, ripples spreading across the surface as if it were water.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Frightened townspeople scatter at the sound of armored patrols.",
      "visual_description": "A narrow alley echoes with metallic footsteps. Quick, shadowy figures dart behind barrels and crates. The oracle lamp dims its glow.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "Mara discovers a secret tunnel under a collapsed bell tower.",
      "visual_description": "A fallen bell lies half-buried in rubble. Mara lifts a trapdoor hidden beneath it, revealing a dark stairwell. The tin fox's eyes glow blue.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver emerges from a window high in the cursed tower.",
      "visual_description": "A shattered window on the tower's third floor. The glass diver climbs out, diving helmet dripping with condensation. Inside, strange lights flicker.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The sleeping tax collector is carried through a magic door.",
      "visual_description": "A glowing door inscribed with runes stands ajar. The tin fox pulls the sleeping tax collector's sleeve as Mara pushes the door open.",
      "characters": ["sleeping_tax_collector", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Old royal banners hang torn in a grand hall.",
      "visual_description": "A vast hall with a collapsed ceiling. Tattered banners bearing faded crests droop from iron hooks. Dust motes swirl in the light.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox scouts ahead past armored patrols.",
      "visual_description": "The tin fox peeks around a corner, its key-wind tail still. Armored figures march in the distance, their footsteps echoing.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Mara reads a riddle on a magic door to the escape route.",
      "visual_description": "A stone door covered in glowing script. Mara squints, compass in hand, as the oracle lamp casts its light on the words.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver returns through a window, carrying a key.",
      "visual_description": "The glass diver slides through a window pane, holding a rusted iron key. The oracle lamp flares in approval.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector wakes briefly and stamps a map.",
      "visual_description": "The sleeping tax collector blinks, pulls a stamp from his sleeve, and stamps Mara's map before slumping back to sleep.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The group gathers at the base of the escape bridge.",
      "visual_description": "A stone bridge arches over a dry moat filled with rubble. The five characters stand together, looking up at the path ahead.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "Armored patrols close in as they cross the bridge.",
      "visual_description": "The bridge trembles under footsteps. Armored figures appear at both ends. The glass diver's helmet glints, and the tin fox bares tiny metal teeth.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The glass diver shatters a mirror behind them, sealing the escape.",
      "visual_description": "At the far side of the bridge, the glass diver hurls a mirror shard against the stone. It explodes into a cascade of silver fragments, blocking the path.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

